begin;
create extension if not exists pgtap with schema extensions;
select extensions.plan(11);
insert into auth.users(id,email) values ('44100000-0000-4000-8000-000000000001','manage-owner@example.test'),('44100000-0000-4000-8000-000000000002','manage-doctor@example.test'),('44100000-0000-4000-8000-000000000003','manage-assistant@example.test');
insert into public.clinics(id,name,timezone) values ('44200000-0000-4000-8000-000000000001','Management A','America/Mexico_City'),('44200000-0000-4000-8000-000000000002','Management B','America/New_York');
insert into public.clinic_members(id,clinic_id,user_id,role,status) values ('44300000-0000-4000-8000-000000000001','44200000-0000-4000-8000-000000000001','44100000-0000-4000-8000-000000000001','owner','active'),('44300000-0000-4000-8000-000000000002','44200000-0000-4000-8000-000000000001','44100000-0000-4000-8000-000000000002','doctor','active'),('44300000-0000-4000-8000-000000000003','44200000-0000-4000-8000-000000000001','44100000-0000-4000-8000-000000000003','assistant','active');
select extensions.ok(has_function_privilege('authenticated','public.manage_professional_availability_exception(text,uuid,uuid,uuid,text,date,text,date,text,boolean,text)','execute') and not has_function_privilege('anon','public.manage_professional_availability_exception(text,uuid,uuid,uuid,text,date,text,date,text,boolean,text)','execute'),'management RPC is authenticated-only');
set local role authenticated; select set_config('request.jwt.claim.sub','44100000-0000-4000-8000-000000000001',true);
select extensions.lives_ok($$select public.manage_professional_availability_exception('create',null,'44200000-0000-4000-8000-000000000001','44300000-0000-4000-8000-000000000002','unavailable','2036-09-14','13:00','2036-09-14','15:00',false,'Comida')$$,'owner creates timed unavailable exception');
select extensions.is((select start_at from public.professional_availability_exceptions where reason='Comida'),timestamptz '2036-09-14 19:00+00','local Mexico start converts to UTC');
select extensions.lives_ok($$select public.manage_professional_availability_exception('create',null,'44200000-0000-4000-8000-000000000001','44300000-0000-4000-8000-000000000002','unavailable','2036-09-20',null,'2036-09-25',null,true,'Vacaciones')$$,'owner creates all-day exception');
select extensions.is((select end_at from public.professional_availability_exceptions where reason='Vacaciones'),timestamptz '2036-09-26 06:00+00','all-day end is exclusive local next day');
select extensions.throws_ok($$select public.manage_professional_availability_exception('create',null,'44200000-0000-4000-8000-000000000001','44300000-0000-4000-8000-000000000002','available','2036-09-14','15:00','2036-09-14','14:00',false,null)$$,'22023',null,'reversed range rejected');
select extensions.is((select count(*)::int from public.professional_availability_exceptions where is_active),2,'two active exceptions exist');
select extensions.lives_ok($$select public.manage_professional_availability_exception('update',(select id from public.professional_availability_exceptions where reason='Comida'),'44200000-0000-4000-8000-000000000001','44300000-0000-4000-8000-000000000002','available','2036-09-14','16:00','2036-09-14','17:00',false,'Apertura')$$,'owner edits exception');
select extensions.lives_ok($$select public.manage_professional_availability_exception('deactivate',(select id from public.professional_availability_exceptions where reason='Vacaciones'),'44200000-0000-4000-8000-000000000001','44300000-0000-4000-8000-000000000002',null,null,null,null,null,false,null)$$,'owner deactivates exception');
select extensions.is((select count(*)::int from public.professional_availability_exceptions where is_active),1,'deactivated exception is not active');
select set_config('request.jwt.claim.sub','44100000-0000-4000-8000-000000000003',true);
select extensions.throws_ok($$select public.manage_professional_availability_exception('create',null,'44200000-0000-4000-8000-000000000001','44300000-0000-4000-8000-000000000002','unavailable','2036-09-14','09:00','2036-09-14','10:00',false,null)$$,'42501',null,'assistant cannot write');
select extensions.finish(); rollback;
